/**
 * INDX macros the plugin can create when another macro calls them and they are missing. Every
 * generated file is a skeleton: only a safe early exit is active, the rest is commented out, so it does
 * nothing until the user edits it for their printer. Existing files are never overwritten.
 */

export interface IndxMacro {
	file: string;
	/** Start of the INDX_variables.g section header whose page warns when the file is called but missing */
	sectionMatch: string;
	template: string;
}

const PRIME_SKELETON = `; INDX_Prime.g - prime and wipe after a pickup
; Generated by the INDX Tuner plugin as a skeleton. Only the cold check below is active:
; edit the rest for your printer and remove the ";" in front of the code.
;
; Called by INDX_TC_POST.g as  M98 P"INDX_Prime.g" T<target temperature>
; T is the temperature the tool is set to, not a tool number.
; Settings used (INDX Tuner, Prime & Wipe): INDX_prime_e, INDX_prime_feed, INDX_prime_retract,
; INDX_prime_retract_feed, INDX_prime_wipe_feed.

; cold pickup (below the cold-extrusion temperature, M302, 160 C by default): nothing to prime
if !exists(param.T) || param.T < heat.coldExtrudeTemperature
  M99

; --- move to your purge / cleaning position here ---

;M116 P{state.currentTool}      ; wait for the tool's heater
;G1 E{global.INDX_prime_e} F{global.INDX_prime_feed}
;G1 E{-global.INDX_prime_retract} F{global.INDX_prime_retract_feed}

; --- your wipe moves here, e.g.  G1 X... F{global.INDX_prime_wipe_feed} ---

; --- move back to a safe position here ---
`;

export const INDX_MACROS: IndxMacro[] = [
	{ file: "INDX_Prime.g", sectionMatch: "prime and wipe", template: PRIME_SKELETON },
];

/** Whether a file is in a directory listing; the SD card ignores case */
export function hasFile(names: Iterable<string>, file: string): boolean {
	const f = file.toLowerCase();
	for (const n of names) {
		if (n.toLowerCase() === f) {
			return true;
		}
	}
	return false;
}
